void AgentHost::handle_agent_tool_call(AgentToolCall call)
{
    if (!m_stream)
        return;

    ActiveStream stream = std::move(*m_stream);
    m_stream.reset();
    stream.message.state = MessageState::Complete;
    m_persistence.document().update_message(stream.conversation_id, stream.message);
    m_persistence.flush();
    send_envelope(Protocol::kAssistantCompleted, json{{"messageId", stream.message.id}}.dump());

    const ToolActivity& proposed =
        m_tools.propose(call.request, stream.message.id, ToolExecutionPacing{call.test_run_ticks}, ToolSource::Agent,
                        stream.conversation_id);
    if (call.await_result) {
        PendingToolContinuation continuation;
        continuation.call_id            = std::move(call.call_id);
        continuation.conversation_id     = stream.conversation_id;
        continuation.user_message_id     = stream.message.in_reply_to;
        m_tool_continuations[proposed.action_id] = std::move(continuation);
        // A call refused at proposal (a stale revision, an invalid patch) was
        // already terminal when the coordinator announced it, before this
        // continuation existed; hand the agent its result now.
        // A plan member waits for the plan's one card, which the person
        // decides after this turn ends; the agent hears it is queued now.
        if (tool_state_terminal(proposed.state) || (!proposed.plan_id.empty() && proposed.state == ToolState::Pending)) {
            const ToolActivity answered = proposed;
            continue_after_tool(answered);
        }
    } else {
        start_next_queued_reply();
    }
    send_conversations();
}

bool AgentHost::remember_setup_intent(const ToolActivity& activity)
{
    const json arguments = json::parse(activity.arguments_json, nullptr, false);
    if (arguments.is_discarded() || !arguments.is_object() || !arguments.contains("intent") ||
        !arguments["intent"].is_string())
        return false;
    // A change made outside a chat -- an MCP client, say -- has no chat to be
    // the record of, so it leaves no intent behind.
    const std::string conversation_id = m_persistence.document().conversation_of_message(activity.correlation_id);
    if (conversation_id.empty())
        return false;
    if (!m_persistence.document().set_setup_intent(conversation_id, arguments["intent"].get<std::string>()))
        return false;
    m_persistence.commit();
    // An intent written on a chat you are not looking at changes nothing on
    // screen, so it is not worth a push of its own.
    return conversation_id == m_persistence.document().active_conversation_id();
}

bool AgentHost::remember_agent_authored(const ToolActivity& activity)
{
    const json result = json::parse(activity.result_json, nullptr, false);
    // A patch that changed nothing wrote nothing, so it authored nothing.
    if (result.is_discarded() || !result.is_object() || !result.value("applied", false))
        return false;
    const auto changes = result.find("changes");
    if (changes == result.end() || !changes->is_array())
        return false;
    // Both the requested changes and the dependencies Orca normalized as a
    // consequence: the reader did not type either of them. The requested ones
    // are serialized first, so the tool result's 64-entry cap can only ever
    // cost us a dependency, never a setting the agent was asked for.
    for (const json& change : *changes)
        if (change.is_object() && change.contains("key") && change["key"].is_string() &&
            change.contains("after") && change["after"].is_string())
            m_agent_authored[change["key"].get<std::string>()] = change["after"].get<std::string>();
    return true;
}

void AgentHost::rebuild_agent_authored()
{
    m_agent_authored.clear();
    // Left unbound so the next context adopts whatever preset is in force
    // without mistaking the rebuild itself for a preset switch.
    m_agent_authored_preset.reset();
    for (const ToolActivity& activity : m_persistence.document().activities())
        if (activity.state == ToolState::Succeeded && activity.tool == "settings_apply_patch")
            remember_agent_authored(activity);
}

std::set<std::string> AgentHost::agent_authored_keys(const Workspace::WorkspaceSnapshot& snapshot)
{
    if (!m_agent_authored_preset)
        m_agent_authored_preset = snapshot.setup.process_preset;
    else if (*m_agent_authored_preset != snapshot.setup.process_preset) {
        m_agent_authored.clear();
        m_agent_authored_preset = snapshot.setup.process_preset;
    }
    std::set<std::string> keys;
    for (const Workspace::PresetDelta& delta : snapshot.preset_deltas) {
        const auto found = m_agent_authored.find(delta.key);
        // The agent's only while the value it applied is the value in force.
        // Edit that setting by hand and the delta becomes yours again.
        if (found != m_agent_authored.end() && found->second == delta.value)
            keys.insert(delta.key);
    }
    return keys;
}

void AgentHost::continue_after_tool(const ToolActivity& activity)
{
    const auto found = m_tool_continuations.find(activity.action_id);
    if (found == m_tool_continuations.end())
        return;

    PendingToolContinuation continuation = found->second;
    m_tool_continuations.erase(found);

    const bool queued = activity.state == ToolState::Pending;
    json output{{"state", queued ? "queued" : tool_state_name(activity.state)}};
    // A session about something other than the project is never told about
    // the project, in its tool results any more than in its turns.
    if (m_session_profile.include_workspace) {
        const WorkspaceSnapshot current_workspace = m_workspace.snapshot();
        output["actionId"]          = activity.action_id;
        output["workspaceRevision"] = current_workspace.revision;
        output["workspace"]         = context_json(current_workspace, agent_authored_keys(current_workspace));
    }
    if (!activity.result_json.empty())
        output["result"] = parsed_or_object(activity.result_json);
    if (activity.error)
        output["error"] = json{{"code", activity.error->code}, {"message", activity.error->message},
                                {"details", json::parse(activity.error->details_json)}};
    if (m_session_tool_output)
        if (std::optional<json> own = m_session_tool_output(activity))
            output = std::move(*own);
    if (queued) {
        output["planId"]  = activity.plan_id;
        output["message"] = "Queued in plan " + activity.plan_id +
                            ". Propose the plan's remaining calls with the same planId, then end your turn and ask the user to "
                            "approve the plan card. Nothing has run yet.";
    }

    AgentToolResult result;
    result.call_id     = continuation.call_id;
    result.state       = queued ? "queued" : tool_state_name(activity.state);
    result.output_json = output.dump();
    result.image       = activity.image;
    if (!m_agent || !m_agent->continue_after_tool(result)) {
        begin_tool_followup(continuation);
        fail_stream(AgentError{"agent_continuation_failed", "The Agent could not receive the native tool result.", true});
        return;
    }
    begin_tool_followup(continuation);
}

void AgentHost::begin_tool_followup(const PendingToolContinuation& continuation)
{
    ProjectStateDocument& document = m_persistence.document();
    ConversationMessage assistant;
    assistant.id          = document.allocate_message_id();
    assistant.role        = MessageRole::Assistant;
    assistant.state       = MessageState::Streaming;
    assistant.in_reply_to = continuation.user_message_id;
    document.append_message(continuation.conversation_id, assistant, m_persistence.timestamp());
    m_persistence.commit();

    ActiveStream stream;
    stream.conversation_id = continuation.conversation_id;
    stream.message         = assistant;
    m_stream               = std::move(stream);
    send_envelope(Protocol::kAssistantStarted,
                  json{{"messageId", assistant.id}, {"inReplyTo", assistant.in_reply_to}, {"attempt", assistant.attempt}}.dump());
}

void AgentHost::pump_stream()
{
    if (m_title && m_handshake) {
        pump_conversation_title();
        return;
    }
    if (!m_stream || !m_handshake)
        return;

