}

/* Chat navigation: the header and configuration footer stay outside the
   scrolling content so both remain reachable in a short or narrow dock. */
.chat-content { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.chat-content[hidden] { display: none; }

/* Adding a printer takes Home's workspace; editing keeps the narrow panel. */
.app--printer-setup {
  background: var(--surface-canvas);
  padding: 16px;
}
.app--printer-setup > .chat-content,
.app--printer-setup > .printer-connection {
  width: 100%;
  max-width: var(--printer-setup-width);
  margin-inline: auto;
}
.app--printer-setup .printer-header {
  height: auto;
  flex-wrap: wrap;
  justify-content: space-between;
  border-bottom: none;
  padding: 8px 16px;
}
.printer-setup-title {
  margin: 16px 16px 8px;
  font: var(--font-page-title);
}
.app--printer-setup .printer-setup-explanation {
  margin: 0;
  padding: 0 16px 16px;
}
.chat-header, .chat-list-header {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  height: 44px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 8px 12px;
}

.printer-cards-compact .printer-card-picture {
  width: 44px;
  height: 34px;
}

.printer-chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 0;
}

.printer-chip {
  padding: var(--button-secondary-padding);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-standard);
  background: var(--surface-canvas);
  cursor: pointer;
  font: var(--font-label);
  color: var(--text-primary);
}

.printer-chip:hover:enabled {
  border-color: var(--border-strong);
}

.printer-chip:disabled {
  color: var(--action-disabled);
  cursor: default;
}

/* Same shape as the others; the fill is the only difference. */
.printer-chip-primary {
  border-color: var(--action-primary);
  background: var(--action-primary);
  font: var(--font-label-bold);
  color: var(--action-primary-text);
}

/* A card a newer answer replaced, or the person refused: still in the
   thread, as one quiet line, so the conversation reads in order. */
.printer-cards-collapsed {
  padding: 4px 12px;
  border-left: 2px solid var(--border-subtle);
  font: var(--font-label);
  color: var(--text-tertiary);
  text-decoration: line-through;
