161	std::vector<std::string> PrinterConversation::session_tools(ConversationMode mode)
162	{
163	    if (mode == ConversationMode::Connect)
164	        return {};
165	    // One tool per mode. A Change session that could identify a printer
166	    // could also clear the card of the printer it is about.
167	    return {mode == ConversationMode::Add ? "printer_identify" : "printer_change"};
168	}
169	
170	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
171	{
172	    m_mode         = mode;
173	    m_printer_name = printer_name;
174	    m_printer      = {};
175	    m_proposal     = {};
176	    m_blocks       = json::array();
177	    m_next_block   = 1;
178	    m_stated_nozzle.clear();
179	    m_undo.reset();
180	    // A new session's page writes its instructions again.
181	    m_instructions.clear();
182	    m_network.clear();
183	    m_opened = false;
184	    m_added.clear();
185	    m_manual_applied = false;
186	    m_connection_name.clear();
187	    m_connection_view = nullptr;
188	
189	    m_facts = {};
190	    // A printer this app has not saved cannot be changed, and the header's
191	    // menu can name one: a system profile is selected until the person adds
192	    // a printer of their own. Adding one is what there is to do.
193	    if (m_mode == ConversationMode::Change) {
194	        const std::vector<SavedPrinter> saved = m_backend.saved_printers();
195	        if (std::none_of(saved.begin(), saved.end(),
196	                         [this](const SavedPrinter& printer) { return printer.name == m_printer_name; })) {
197	            m_mode = ConversationMode::Add;
198	            m_printer_name.clear();
199	        }
200	    }
201	
202	    if (m_mode == ConversationMode::Connect) {
203	        m_connection_name = printer_name;
204	        m_backend.prepare_connection(printer_name);
205	        refresh_connection();
206	    } else if (m_mode == ConversationMode::Change)
207	        read_saved_printer();
208	    else {
209	        refresh_network();
210	        // A photo is the fastest way in, and the printers already on the
211	        // network are the fastest of all. Both belong under the opening,
212	        // where the person is deciding what to say.
213	        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
214	        if (!m_network.empty()) {
215	            json found = json::array();
216	            for (const DiscoveredPrinter& printer : m_network) {
217	                json entry{{"deviceId", printer.stable_id},
218	                           {"name", printer.name},
219	                           {"serial", printer.stable_id},
220	                           {"online", printer.connected}};
221	                // What "Use this" would put on the card, so the page can say
222	                // so to the model when it is tapped.
223	                if (const CatalogPrinter* model = model_of(printer)) {
224	                    const bool reported = reports_nozzle(printer, *model);
225	                    entry["match"] = json{{"name", model->display_name()},
226	                                          {"nozzle", reported ? printer.nozzle_diameter : assumed_nozzle(*model)},
227	                                          {"reported", reported}};
228	                }
229	                found.push_back(std::move(entry));
230	            }
231	            m_blocks.push_back(json{{"id", next_block_id()},
232	                                    {"seq", m_blocks.size() + 1},
233	                                    {"afterMessageId", ""},
234	                                    {"kind", "network"},
235	                                    {"printers", std::move(found)}});
236	        }
237	    }
238	    m_host.session_changed();
239	}
