255	void PrinterConversation::read_saved_printer()
256	{
257	    for (const SavedPrinter& saved : m_backend.saved_printers())
258	        if (saved.name == m_printer_name)
259	            m_printer = saved;
260	
261	    m_facts         = {};
262	    m_facts.printer = m_printer.name.empty() ? m_printer_name : m_printer.name;
263	    m_facts.nozzle  = m_printer.nozzle;
264	    // The plate a printer is set up with is a starting point rather than a
265	    // reading: it is the plate its profile ships with until a project says
266	    // otherwise.
267	    m_facts.plate            = m_printer.plate;
268	    m_facts.plate_provenance = "assumed";
269	    m_facts.ams              = m_printer.ams;
270	    m_facts.spools           = m_printer.spools;
