275	json PrinterConversation::context_json() const
276	{
277	    json context = json::object();
278	    if (m_mode == ConversationMode::Add) {
279	        json printers = json::array();
280	        for (const CatalogPrinter& printer : m_backend.catalog())
281	            printers.push_back(json::array({printer.id, printer.display_name(), printer.build_volume}));
282	        json network = json::array();
283	        for (const DiscoveredPrinter& found : m_network)
284	            network.push_back(json{{"name", found.name}, {"serial", found.stable_id}});
285	        context["printers"] = std::move(printers);
286	        context["network"]  = std::move(network);
287	    } else {
288	        json nozzles = json::array();
289	        for (double size : m_printer.nozzles)
290	            nozzles.push_back(size);
291	        context["printer"] = json{{"name", m_printer.name},
292	                                  {"model", m_printer.model},
293	                                  {"nozzle", m_printer.nozzle},
294	                                  {"nozzles", std::move(nozzles)},
295	                                  {"spools", spools_json(m_printer.spools)},
296	                                  {"connected", m_printer.connected}};
297	    }
298	    return context;
