301	Agent::AgentSessionProfile PrinterConversation::profile() const
302	{
303	    Agent::AgentSessionProfile profile;
304	    // The tools are the app's to decide, one per mode; the words are the
305	    // page's (printerInstructions.ts), sent with printer_instructions.
306	    profile.tool_names   = m_added.empty() && m_connection_name.empty() ? session_tools(m_mode) : std::vector<std::string>();
307	    profile.instructions = m_instructions;
308	    // This conversation is about a machine, not about the open project, and
309	    // what the person taps on its cards reaches the model as the app's notes.
310	    profile.include_workspace = false;
311	    profile.notes_in_context  = true;
312	    return profile;
