325	                                       {"spools", spools_json(m_facts.spools)},
326	                                       {"provenance", m_facts.filament_provenance}}}};
327	    return json{{"mode", m_mode == ConversationMode::Add ? "add" : m_mode == ConversationMode::Connect ? "connect" : "change"},
328	                {"facts", facts},
329	                {"blocks", m_blocks},
330	                // A printer is on its card: Add saves it, and it can be refused.
331	                {"canAdd", m_proposal.valid},
332	                {"added", std::move(added)},
333	                {"manualApplied", m_manual_applied},
334	                {"connection", m_connection_view},
335	                // The facts the page's instructions for the model state.
336	                {"context", context_json()}};
