434	void PrinterConversation::show_proposal(const CatalogPrinter& printer, double nozzle, bool nozzle_stated,
435	                                        const std::string& block_id, const DiscoveredPrinter* device)
436	{
437	    const std::string filament = printer.filament_for(nozzle);
438	    m_proposal = PrinterProposal{true,
439	                                 block_id,
440	                                 printer.vendor_id,
441	                                 printer.model_id,
442	                                 printer.display_name(),
443	                                 variant_text(nozzle),
444	                                 filament,
445	                                 device != nullptr ? device->stable_id : std::string()};
446	
447	    m_facts                   = {};
448	    m_facts.printer           = printer.display_name();
449	    m_facts.nozzle            = nozzle;
450	    m_facts.nozzle_provenance = nozzle_stated ? "settled" : "assumed";
451	    m_facts.plate             = printer.default_plate;
452	    m_facts.plate_provenance  = "assumed";
453	    // What the printer reported it has loaded is settled; otherwise the card
454	    // assumes the profile's filament.
455	    const std::vector<PrinterSpool> loaded = device != nullptr ? reported_spools(*device) : std::vector<PrinterSpool>();
456	    m_facts.filament_preset = filament;
457	    if (!loaded.empty()) {
458	        m_facts.ams    = device->ams_name;
459	        m_facts.spools = loaded;
460	    } else
461	        m_facts.filament_provenance = "assumed";
462	}
