464	// -- The session's tools ----------------------------------------------------
465	
466	std::optional<ToolError> PrinterConversation::preflight_tool(ToolHandler handler, ToolActivity& activity) const
467	{
468	    if (handler != ToolHandler::PrinterChange)
469	        return std::nullopt;
470	    if (m_mode != ConversationMode::Change)
471	        return ToolError{"no_printer", "This session is not about a printer the person owns."};
472	
473	    json arguments = json::parse(activity.arguments_json, nullptr, false);
474	    if (!arguments.is_object())
475	        return ToolError{"invalid_arguments", "The printer tool arguments are invalid."};
476	
477	    std::optional<SavedPrinter> now;
478	    for (const SavedPrinter& saved : m_backend.saved_printers())
479	        if (saved.name == m_printer_name)
480	            now = saved;
481	    if (!now)
482	        return ToolError{"printer_gone", "\"" + m_printer_name + "\" was renamed or removed; this panel can no longer change it."};
483	
484	    const bool has_nozzle = said_nozzle(arguments);
485	    const bool has_spools = arguments.contains("spools");
486	    if (!has_nozzle && !has_spools)
487	        return ToolError{"nothing_to_change", "Name the nozzle or the spools that changed."};
488	    const std::string model = now->model.empty() ? now->name : now->model;
489	    if (has_nozzle) {
490	        const double nozzle = arguments["nozzle"].get<double>();
491	        if (!now->nozzles.empty() && !ships(now->nozzles, nozzle))
492	            return ToolError{"unknown_nozzle", "JusPrin supports " + sizes_text(now->nozzles) + " nozzles for " + model + ", but not " +
493	                                                   nozzle_text(nozzle) + ". Ask the person to check the nozzle marking or packaging; do not substitute a size."};
494	    }
495	    const bool nozzle_moves = has_nozzle && arguments["nozzle"].get<double>() != now->nozzle;
496	    const bool spools_move  = has_spools && !same_spools(spools_of(arguments["spools"]), now->spools);
497	    if (!nozzle_moves && !spools_move)
498	        return ToolError{"nothing_to_change", "That is already how this printer is set up: a " + nozzle_text(now->nozzle) +
499	                                                  " nozzle, and spools: " + spools_text(now->spools) + "."};
500	
501	    // What the card states: the change in words, against the printer as it
502	    // is while the card waits.
503	    activity.title = nozzle_moves && spools_move ? "Change nozzle and spools" : nozzle_moves ? "Change nozzle" : "Change spools";
504	    json before = json::object();
505	    if (nozzle_moves)
506	        before["nozzle"] = now->nozzle;
507	    else
508	        arguments.erase("nozzle");
509	    if (spools_move)
510	        before["spools"] = spools_json(now->spools);
511	    else
512	        arguments.erase("spools");
513	    arguments["confirm"]    = json{{"printer", model}, {"before", std::move(before)}};
514	    activity.arguments_json = arguments.dump();
515	    return std::nullopt;
516	}
517	
518	ToolExecutionCoordinator::ExtensionResult PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
519	{
520	    ToolExecutionCoordinator::ExtensionResult result;
521	    if (handler != ToolHandler::PrinterIdentify && handler != ToolHandler::PrinterChange)
522	        return result;
523	
524	    result.handled = true;
525	    if (!m_added.empty() || !m_connection_name.empty()) {
526	        result.error = ToolError{"setup_finished", "The printer is saved. Connection is handled by the person's connection controls."};
527	        return result;
528	    }
529	    const json arguments = json::parse(activity.arguments_json, nullptr, false);
530	    if (!arguments.is_object()) {
531	        result.error = ToolError{"invalid_arguments", "The printer tool arguments are invalid."};
532	        return result;
533	    }
534	
535	    std::optional<ToolError> error;
536	    const json output = handler == ToolHandler::PrinterIdentify ? identify(arguments, activity.correlation_id, error) :
537	                                                                  change(arguments, activity.correlation_id, error);
538	    if (error) {
539	        result.error = std::move(error);
540	        return result;
541	    }
542	    m_host.session_changed();
543	    result.result_json = output.dump();
544	    return result;
545	}
546	
547	std::optional<json> PrinterConversation::tool_output(const ToolActivity& activity) const
548	{
549	    if (activity.tool != "printer_identify" && activity.tool != "printer_change")
550	        return std::nullopt;
551	    if (activity.state == Agent::ToolState::Succeeded)
552	        return json::parse(activity.result_json, nullptr, false);
553	    if (activity.state == Agent::ToolState::Failed && activity.error)
554	        return json{{"error", json{{"code", activity.error->code}, {"message", activity.error->message}}}};
555	    if (activity.state == Agent::ToolState::Rejected && activity.tool == "printer_change")
556	        return json{{"state", "declined"}, {"changed", json::array()}, {"printer", printer_json()}};
557	    return std::nullopt;
558	}
559	
560	json PrinterConversation::identify(const json& arguments, const std::string& message_id, std::optional<ToolError>& error)
561	{
562	    if (m_mode != ConversationMode::Add) {
563	        error = ToolError{"not_adding", "This session is about a printer the person already has."};
564	        return {};
565	    }
566	
567	    std::vector<std::string> ids;
568	    for (const json& id : arguments.at("catalogIds"))
569	        if (std::find(ids.begin(), ids.end(), id.get<std::string>()) == ids.end())
570	            ids.push_back(id.get<std::string>());
571	    if (ids.size() > kMaximumCandidates) {
572	        error = ToolError{"too_many", "More than three fit. Ask one question that narrows it down instead."};
573	        return {};
574	    }
575	
576	    std::vector<const CatalogPrinter*> printers;
577	    for (const std::string& id : ids) {
578	        const CatalogPrinter* printer = catalog_entry(id);
579	        if (printer == nullptr) {
580	            error = ToolError{"unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list."};
581	            return {};
582	        }
583	        printers.push_back(printer);
584	    }
585	
586	    const bool   stated = said_nozzle(arguments);
587	    const double wanted = stated ? arguments["nozzle"].get<double>() : 0.;
588	    if (stated)
589	        for (const CatalogPrinter* printer : printers)
590	            if (!ships(printer->nozzles, wanted)) {
591	                error = ToolError{"unknown_nozzle", "JusPrin supports " + sizes_text(printer->nozzles) +
592	                                                        " nozzles for " + printer->display_name() + ", but not " + nozzle_text(wanted) +
593	                                                        ". Ask the person to check the nozzle marking or packaging; do not substitute a size."};
594	                return {};
595	            }
596	
597	    // The newest answer is the one to act on; earlier cards fold away.
598	    collapse_cards();
599	    const std::string id    = next_block_id();
600	    json              cards = json::array();
601	    json              found = json::array();
602	    for (const CatalogPrinter* printer : printers) {
603	        const double nozzle = stated ? wanted : assumed_nozzle(*printer);
604	        cards.push_back(card_json(*printer, nozzle, printers.size() == 1 ? "add" : "choose", nullptr));
605	        found.push_back(identified_json(*printer, nozzle));
606	    }
607	    m_blocks.push_back(json{{"id", id}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id}, {"kind", "printers"},
608	                            {"printers", std::move(cards)}});
609	    if (stated)
610	        m_stated_nozzle[id] = wanted;
611	
612	    if (printers.size() == 1)
613	        show_proposal(*printers.front(), stated ? wanted : assumed_nozzle(*printers.front()), stated, id, nullptr);
614	    else
615	        // Nothing is settled while two printers are still on the table.
616	        clear_proposal();
617	    return json{{"printers", std::move(found)}};
618	}
619	
620	json PrinterConversation::change(const json& arguments, const std::string& message_id, std::optional<ToolError>& error)
621	{
622	    if (m_mode != ConversationMode::Change || m_printer.name.empty()) {
623	        error = ToolError{"no_printer", "This session is not about a printer the person owns."};
624	        return {};
625	    }
626	    const SavedPrinter before = m_printer;
627	
628	    ChangePrinterRequest request;
629	    request.name = m_printer.name;
630	    if (said_nozzle(arguments))
631	        request.nozzle = arguments["nozzle"].get<double>();
632	    if (arguments.contains("spools"))
633	        request.spools = spools_of(arguments["spools"]);
634	    if (!request.nozzle && !request.spools) {
635	        error = ToolError{"nothing_to_change", "Name the nozzle or the spools that changed."};
636	        return {};
637	    }
638	
639	    SavedPrinter      changed;
640	    const std::string problem = m_backend.change_printer(request, changed);
641	    if (!problem.empty()) {
642	        const std::vector<SavedPrinter> saved = m_backend.saved_printers();
643	        const bool gone = std::none_of(saved.begin(), saved.end(), [this](const SavedPrinter& printer) { return printer.name == m_printer_name; });
644	        error = ToolError{gone ? "printer_gone" : "change_failed", problem};
645	        return {};
646	    }
647	
648	    read_saved_printer();
649	    json       what          = json::array();
650	    json       changed_facts = json::object();
651	    UndoRecord undo;
652	    if (request.nozzle && before.nozzle != m_printer.nozzle) {
653	        what.push_back(json{{"field", "nozzle"}, {"before", before.nozzle}, {"after", m_printer.nozzle}});
654	        changed_facts["nozzle"]   = json{{"before", before.nozzle}, {"after", m_printer.nozzle}};
655	        m_facts.nozzle_provenance = "changed";
656	        undo.nozzle               = before.nozzle;
657	    }
658	    if (request.spools && !same_spools(before.spools, m_printer.spools)) {
659	        what.push_back(json{{"field", "spools"}, {"before", spools_json(before.spools)}, {"after", spools_json(m_printer.spools)}});
660	        changed_facts["spools"] = json{{"before", spools_json(before.spools)}, {"after", spools_json(m_printer.spools)}};
661	        m_facts.filament_provenance = "changed";
662	        undo.spools                 = before.spools;
663	    }
664	
665	    // Undo names the exact change, so it applies directly: the latest change
666	    // is the one it reverses, and an older one's row goes.
667	    if (m_undo)
668	        m_blocks.erase(std::remove_if(m_blocks.begin(), m_blocks.end(),
669	                                      [this](const json& entry) { return entry.value("id", std::string()) == m_undo->block_id; }),
670	                       m_blocks.end());
671	    m_undo.reset();
672	    if (!what.empty()) {
673	        undo.block_id = next_block_id();
674	        m_blocks.push_back(json{{"id", undo.block_id}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
675	                                {"kind", "undo"}, {"changed", std::move(changed_facts)}});
676	        m_undo = std::move(undo);
677	    }
678	    m_host.printers_changed();
679	    return json{{"state", "applied"}, {"changed", std::move(what)}, {"printer", printer_json()}};
680	}
681	
682	// -- Taps on the panel's own cards -------------------------------------------
683	
684	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
685	{
686	    if (type != "printer_action" && type != "printer_instructions" && type != "printer_opening")
687	        return false;
688	
689	    if (type == "printer_instructions") {
690	        // Bounded: the page's words become every request's system prompt.
691	        const std::string text = payload.value("text", std::string());
692	        if (text.size() <= kInstructionsLimit && text != m_instructions) {
693	            m_instructions = text;
694	            m_host.profile_changed();
695	        }
696	        return true;
697	    }
698	    if (type == "printer_opening") {
699	        post_opening(payload.value("text", std::string()));
700	        return true;
701	    }
702	    const std::string action = payload.value("action", std::string());
703	    const std::string id     = payload.value("id", std::string());
704	    const std::string note   = page_note(payload);
705	    if (action == "close")
706	        m_host.close_panel(m_added.size() == 1 ? &m_facts : nullptr);
707	    else if (action == "connection_refresh") {
708	        refresh_connection();
709	        m_host.session_changed();
710	    } else if (action == "connect") {
711	        const bool allowed = (m_mode != ConversationMode::Add && id == m_printer_name) ||
712	            std::any_of(m_added.begin(), m_added.end(), [&](const SavedPrinter& p) { return p.name == id; });
713	        if (!allowed)
714	            return true;
715	        m_connection_name = id;
716	        m_host.profile_changed();
717	        m_backend.prepare_connection(id);
718	        refresh_connection();
719	        m_host.session_changed();
720	    } else if (action == "connection_sign_in" && !m_connection_name.empty()) {
721	        const auto info = m_backend.connection(m_connection_name);
722	        if (info.provider == "bambu" && info.state != "unavailable" && !info.signed_in)
723	            m_backend.sign_in_to_bambu();
724	        refresh_connection();
725	        m_host.session_changed();
726	    } else if (action == "connection_start" && !m_connection_name.empty()) {
727	        const auto problem = m_connection_view.value("provider", std::string()) == "host" ?
728	            m_backend.connect_host(m_connection_name, payload.value("hostType", std::string()),
729	                                   payload.value("address", std::string()), payload.value("accessCode", std::string())) :
730	            m_backend.connect_printer(m_connection_name, payload.value("deviceId", std::string()),
731	                                      payload.value("accessCode", std::string()));
732	        refresh_connection();
733	        if (!problem.empty()) {
734	            m_connection_view["state"] = "failed";
735	            m_connection_view["message"] = problem;
736	        }
737	        m_host.printers_changed();
738	        m_host.session_changed();
739	    }
740	    else if ((!m_added.empty() || !m_connection_name.empty()) && action != "manual_setup")
741	        return true;
742	    else if (action == "manual_setup") {
743	        if (!m_connection_name.empty()) {
744	            m_backend.open_printer_settings(m_connection_name);
745	            refresh_connection();
746	            m_host.session_changed();
747	        } else if (m_mode == ConversationMode::Add) {
748	            if (!m_added.empty())
749	                return true;
750	            // The wizard takes over from here; whatever it installed is on
751	            // the printer list the panel returns to.
752	            const auto result = m_backend.run_manual_setup();
753	            m_added = result.added;
754	            m_host.profile_changed();
755	            m_manual_applied = result.applied;
756	            if (m_added.size() == 1) {
757	                m_facts = {};
758	                m_facts.printer = m_added.front().name;
759	                m_facts.nozzle = m_added.front().nozzle;
760	            }
761	            if (!m_added.empty())
762	                m_proposal = {};
763	            m_host.printers_changed();
764	            m_host.session_changed();
765	        } else {
766	            // OrcaSlicer's own printer settings, as "Printer settings…" did
767	            // before this panel existed. It closes back into this session,
768	            // which restates the printer as it now is.
769	            m_backend.open_printer_settings(m_printer_name);
770	            read_saved_printer();
771	            m_host.printers_changed();
772	            m_host.session_changed();
773	        }
774	    } else if (action == "add")
775	        add_proposed_printer();
776	    else if (action == "reject")
777	        reject_proposal(note);
778	    else if (action == "network_pick")
779	        use_network_printer(id, note);
780	    else if (action == "candidate_pick")
781	        choose_candidate(id, payload.value("blockId", std::string()), note);
782	    else if (action == "undo")
783	        undo_change(id, note);
784	    return true;
785	}
786	
787	void PrinterConversation::add_proposed_printer()
788	{
789	    if (!m_proposal.valid)
790	        return;
791	
792	    AddPrinterRequest request;
793	    request.vendor_id = m_proposal.vendor_id;
794	    request.model_id  = m_proposal.model_id;
795	    request.variant   = m_proposal.variant;
796	    request.material  = m_proposal.material;
797	    request.name      = m_proposal.model_name;
798	    request.device_id = m_proposal.device_id;
799	    // Adding never authenticates. Credentials belong only to the subsequent
800	    // connection gesture, so a failed connection cannot repeat this save.
801	
802	    SavedPrinter      added;
803	    const std::string problem = m_backend.add_printer(request, added);
804	    if (!problem.empty()) {
805	        // One error at a time, in the thread, with what to do about it.
806	        m_host.post_note(problem);
807	        m_host.session_changed();
808	        return;
809	    }
810	    // Keep the receipt open; optional connection targets this saved identity.
811	    if (added.name.empty())
812	        throw std::logic_error("A successful add did not identify its saved printer");
813	    m_added = {added};
814	    m_host.profile_changed();
815	    m_facts.printer = added.name;
816	    m_proposal = {};
817	    m_host.printers_changed();
818	    m_host.session_changed();
819	}
820	
821	void PrinterConversation::refresh_connection()
822	{
823	    if (m_connection_name.empty())
824	        return;
825	    const auto info = m_backend.connection(m_connection_name);
826	    json candidates = json::array();
827	    for (const auto& candidate : info.candidates)
828	        candidates.push_back(json{{"id", candidate.id}, {"name", candidate.name}, {"address", candidate.address}, {"lanMode", candidate.lan_mode}});
829	    m_connection_view = json{{"name", m_connection_name}, {"provider", info.provider}, {"state", info.state},
830	                            {"message", info.message}, {"deviceId", info.device_id}, {"candidates", candidates},
831	                            {"address", info.address}, {"hostType", info.host_type}, {"signedIn", info.signed_in}, {"nozzleMismatch", info.nozzle_mismatch}};
832	}
833	
834	void PrinterConversation::use_network_printer(const std::string& device_id, const std::string& note)
835	{
836	    refresh_network();
837	    const auto found = std::find_if(m_network.begin(), m_network.end(),
838	                                    [&device_id](const DiscoveredPrinter& printer) { return printer.stable_id == device_id; });
839	    // The page wrote its note from the printer as the list showed it; these
840	    // two are what the app finds out only now.
841	    if (found == m_network.end()) {
842	        m_host.post_note("The person chose the network printer " + device_id + ", but it is no longer on the network.");
843	        m_host.session_changed();
844	        m_host.start_turn();
845	        return;
846	    }
847	
848	    const CatalogPrinter* printer = model_of(*found);
849	    if (printer == nullptr) {
850	        // Only the model can ask what it is.
851	        m_host.post_note("The person chose the network printer " + found->stable_id + ", which reports the model id \"" +
852	                         found->device_model_id + "\"; nothing in the printer list has that model id.");
853	        m_host.session_changed();
854	        m_host.start_turn();
855	        return;
856	    }
857	
858	    // What the printer reported is settled; only what it did not say is
859	    // assumed.
860	    const bool        reported = reports_nozzle(*found, *printer);
861	    const double      nozzle   = reported ? found->nozzle_diameter : assumed_nozzle(*printer);
862	    const std::string anchor   = note.empty() ? std::string() : m_host.post_note(note);
863	
864	    collapse_cards();
865	    const std::string id = next_block_id();
866	    m_blocks.push_back(json{{"id", id},
867	                            {"seq", m_blocks.size() + 1},
868	                            {"afterMessageId", anchor},
869	                            {"kind", "printers"},
870	                            {"printers", json::array({card_json(*printer, nozzle, "add", &*found)})}});
871	    show_proposal(*printer, nozzle, reported, id, &*found);
872	    m_host.session_changed();
873	    // Selection needs conversational guidance now that no summary is pinned.
874	    m_host.start_turn();
875	}
876	
877	void PrinterConversation::choose_candidate(const std::string& catalog_id, const std::string& block_id, const std::string& note)
878	{
879	    const CatalogPrinter* chosen = catalog_entry(catalog_id);
880	    if (chosen == nullptr)
881	        return;
882	    json* card = block(block_id);
883	    if (card == nullptr) {
884	        // An older page names no card: the newest one with this printer.
885	        for (json& entry : m_blocks)
886	            if (entry.value("kind", std::string()) == "printers")
887	                for (const json& printer : entry.value("printers", json::array()))
888	                    if (printer.value("catalogId", std::string()) == catalog_id)
889	                        card = &entry;
890	    }
891	    if (card == nullptr)
892	        return;
893	
894	    const std::string card_id = card->value("id", std::string());
895	    const auto        stated  = m_stated_nozzle.find(card_id);
896	    const double      nozzle  = stated != m_stated_nozzle.end() ? stated->second : assumed_nozzle(*chosen);
897	
898	    // The card keeps only the printer chosen, now with Add.
899	    for (json& printer : (*card)["printers"])
900	        if (printer.value("catalogId", std::string()) == catalog_id) {
901	            printer["action"] = "add";
902	            (*card)["printers"] = json::array({printer});
903	            break;
904	        }
905	    show_proposal(*chosen, nozzle, stated != m_stated_nozzle.end(), card_id, nullptr);
906	    // The page wrote it from what this card assumes, which is what Add now
907	    // saves.
908	    if (!note.empty())
909	        m_host.post_note(note);
910	    m_host.session_changed();
911	    m_host.start_turn();
912	}
913	
914	void PrinterConversation::reject_proposal(const std::string& note)
915	{
916	    if (!m_proposal.valid)
917	        return;
918	    if (json* card = block(m_proposal.block_id))
919	        (*card)["collapsed"] = true;
920	    clear_proposal();
921	    if (!note.empty())
922	        m_host.post_note(note);
923	    m_host.session_changed();
924	    // Only the model can decide what to ask next.
925	    m_host.start_turn();
926	}
927	
928	void PrinterConversation::undo_change(const std::string& block_id, const std::string& note)
929	{
930	    if (!m_undo || m_undo->block_id != block_id || m_mode != ConversationMode::Change)
931	        return;
932	
933	    ChangePrinterRequest request;
934	    request.name   = m_printer.name;
935	    request.nozzle = m_undo->nozzle;
936	    request.spools = m_undo->spools;
937	
938	    SavedPrinter      changed;
939	    const std::string problem = m_backend.change_printer(request, changed);
940	    if (!problem.empty()) {
941	        m_host.post_note("Undo did not go through: " + problem);
942	        m_host.session_changed();
943	        return;
944	    }
945	
946	    m_blocks.erase(std::remove_if(m_blocks.begin(), m_blocks.end(),
947	                                  [&block_id](const json& entry) { return entry.value("id", std::string()) == block_id; }),
948	                   m_blocks.end());
949	    m_undo.reset();
950	    read_saved_printer();
951	    // The page wrote it from the undo row, which states exactly what is put
952	    // back.
953	    if (!note.empty())
954	        m_host.post_note(note);
955	    m_host.printers_changed();
956	    m_host.session_changed();
957	}
