1173	// Answers each turn with text, or with the one tool call it was given, and
1174	// records every request and tool result the host hands it.
1175	class ScriptedAgent final : public Agent::IAgentService
1176	{
1177	public:
1178	    std::optional<Agent::ToolRequest>   call;
1179	    std::vector<Agent::AgentRequest>    requests;
1180	    std::vector<Agent::AgentToolResult> results;
1181	
1182	    bool ready() const override { return true; }
1183	    bool busy() const override { return m_active; }
1184	    bool start(const Agent::AgentRequest& request) override
1185	    {
1186	        requests.push_back(request);
1187	        m_active = true;
1188	        if (request.purpose == Agent::AgentRequest::Purpose::ConversationTitle) {
1189	            m_events.push_back(Agent::AgentEvent::delta("Printer"));
1190	            m_events.push_back(Agent::AgentEvent::completed());
1191	        } else if (call) {
1192	            m_events.push_back(Agent::AgentEvent::tool_call({"call-" + std::to_string(requests.size()), *call, true}));
1193	            call.reset();
1194	        } else {
1195	            m_events.push_back(Agent::AgentEvent::delta("Understood."));
1196	            m_events.push_back(Agent::AgentEvent::completed());
1197	        }
1198	        return true;
1199	    }
1200	    bool continue_after_tool(const Agent::AgentToolResult& result) override
1201	    {
1202	        results.push_back(result);
1203	        m_events.push_back(Agent::AgentEvent::delta("Done."));
1204	        m_events.push_back(Agent::AgentEvent::completed());
1205	        return true;
1206	    }
1207	    void cancel() override
1208	    {
1209	        m_active = false;
1210	        m_events.clear();
1211	    }
1212	    std::optional<Agent::AgentEvent> poll() override
1213	    {
1214	        if (m_events.empty())
1215	            return std::nullopt;
1216	        Agent::AgentEvent event = std::move(m_events.front());
1217	        m_events.pop_front();
1218	        if (event.kind == Agent::AgentEventKind::Completed || event.kind == Agent::AgentEventKind::Failed)
1219	            m_active = false;
1220	        return event;
1221	    }
1222	
1223	private:
1224	    std::deque<Agent::AgentEvent> m_events;
1225	    bool                          m_active{false};
1226	};
