    name: 'Prusa MK3S',
    buildVolume: '250 × 210 × 210 mm',
    picture: '',
    action: 'add',
    assumed: { nozzle: 0.4, plate: '', filament: 'Prusa Generic PLA' },
    ...overrides,
  };
