import re, sys
path, unused = sys.argv[1], set(sys.argv[2].split(','))
css = open(path).read()

def uses_unused(selector):
    return any(re.search(r'\.' + re.escape(c) + r'(?![a-zA-Z0-9_-])', selector) for c in unused)

def prune(text):
    out, i, n = [], 0, len(text)
    pending_comment = ''
    while i < n:
        # whitespace and comments are held until we know whether the next rule survives
        m = re.match(r'(\s*(/\*.*?\*/)?)', text[i:], re.S)
        if m and m.group(2):
            pending_comment += m.group(1); i += len(m.group(1)); continue
        ws = re.match(r'\s*', text[i:]).group(0)
        if i + len(ws) >= n:
            out.append(pending_comment + ws); break
        start = i + len(ws)
        brace = text.index('{', start)
        selector = text[start:brace]
        depth, j = 0, brace
        while True:
            if text[j] == '{': depth += 1
            elif text[j] == '}':
                depth -= 1
                if depth == 0: break
            j += 1
        body = text[brace + 1:j]
        if selector.strip().startswith('@'):
            if selector.strip().startswith('@keyframes'):
                out.append(pending_comment + ws + text[start:j + 1])
            else:
                inner = prune(body)
                if inner.strip():
                    out.append(pending_comment + ws + selector + '{' + inner + '}')
                elif pending_comment:
                    pass
        else:
            parts = [p for p in selector.split(',')]
            keep = [p for p in parts if not uses_unused(p)]
            if keep:
                sel = ','.join(keep)
                if len(keep) != len(parts):
                    sel = sel.strip() + ' '
                    sel = '\n' + sel if selector.startswith('\n') else sel
                out.append(pending_comment + ws + (sel if len(keep) != len(parts) else selector) + text[brace:j + 1])
        pending_comment = ''
        i = j + 1
    return ''.join(out)

new = prune(css)
new = re.sub(r'\n{3,}', '\n\n', new)
open(path, 'w').write(new)
