-.printer-connection .footnote { font: var(--font-metadata); color: var(--text-secondary); }
-.printer-connection form, .printer-connection label { display: flex; flex-direction: column; gap: 8px; }
-.printer-connection form { gap: 16px; }
-.printer-connection input, .printer-connection select {
-.printer-connection-actions { display: flex; flex-wrap: wrap; gap: 8px; }
-.printer-connection-region { flex: 0 1 auto; max-height: 60%; overflow: auto; }
}

/* Chat navigation: the header and configuration footer stay outside the
   scrolling content so both remain reachable in a short or narrow dock. */
.chat-content { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.chat-content[hidden] { display: none; }

/* Adding a printer takes Home's workspace; editing keeps the narrow panel. */
.app--printer-setup {
  background: var(--surface-canvas);
  padding: 16px;
}
.app--printer-setup > .chat-content {
  width: 100%;
  max-width: var(--printer-setup-width);
  margin-inline: auto;
}
.app--printer-setup .printer-header {
  height: auto;
  flex-wrap: wrap;
  justify-content: space-between;
  border-bottom: none;
  padding: 8px 16px;
}
.chat-header, .chat-list-header {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  height: 44px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);

