{
    live_panel()->close();
    wxYield();
    if (!m_live_printer.empty())
        Printers::remove_named_printer(*m_plater, nullptr, m_live_printer);
    SetupCommands::select_printer_preset(*m_plater, kSetupFixturePrinter);
    finish();
}

