toolUseResult.originalFile:
// The replies an assistant offers to tap. Its instructions tell it to end a
// message with one line, "Choices: first | second | third"; the page draws
// that line as chips instead of text. A message without the line is just
// text, and the person types their answer.

const PREFIX = 'Choices:';

function lastLine(text: string): { before: string; line: string } {
  const trimmed = text.trimEnd();
  const cut = trimmed.lastIndexOf('\n');
  return { before: cut < 0 ? '' : trimmed.slice(0, cut), line: trimmed.slice(cut + 1).trim() };
}

// A finished message: its text without the choices line, and the choices.
export function splitChoices(text: string): { body: string; choices: string[] } {
  const { before, line } = lastLine(text);
  if (!line.startsWith(PREFIX)) return { body: text, choices: [] };
  const choices = line
    .slice(PREFIX.length)
    .split('|')
    .map((choice) => choice.trim())
    .filter(Boolean);
  return { body: before.trimEnd(), choices };
}

// A message still streaming: the same text, minus a last line that is, or
// may yet become, the choices line, so it never shows as text first.
export function withoutPartialChoices(text: string): string {
  const { before, line } = lastLine(text);
  const mayBeChoices = line.length > 0 && (line.startsWith(PREFIX) || PREFIX.startsWith(line));
  return mayBeChoices ? before.trimEnd() : text;
}

