                                    if (card() == nullptr || card()->state != Agent::ToolState::Pending)
                                        say("Yes, connect it");
                                },
                                {},
                                [this, card] {
                                    live_print_new();
                                    live_print_calls();
                                    check(card() != nullptr && card()->state == Agent::ToolState::Pending,
                                          "live_connect_asks_for_the_code_on_its_card");
                                }});
'''+s[b:]
a=s.index('        live_say("ok, I have the code. Connect JusPrin Fake A1 mini", [this, card] {')
s=s.replace('        live_say("ok, I have the code. Connect JusPrin Fake A1 mini", [this, card] {','        live_say("ok, I have the code now. Connect it", [this, card] {',1)
# retry only when the first attempt did not verify
a=s.index('        // A first attempt the printer interrupted is retried as a person would.')
b=s.index('        approve("tap Connect again", "live_a_retry_connects");')+len('        approve("tap Connect again", "live_a_retry_connects");\n')
s=s[:a]+s[b:]
open(p,'w').write(s)
EOF
