1	// What the printer panel tells the model, written from the facts the app
2	// sends in the session's context.
3	
4	import { describe, expect, it } from 'vitest';
5	import { readFileSync, writeFileSync } from 'node:fs';
6	import { join } from 'node:path';
7	import type { PrinterSessionPayload } from './bridge/protocol';
8	import { printerInstructions } from './printerInstructions';
9	import { splitChoices } from './replyChoices';
10	
11	function session(overrides: Partial<PrinterSessionPayload>): PrinterSessionPayload {
12	  return { mode: 'add', printerName: '', blocks: [], context: {}, ...overrides };
13	}
14	
15	const add = session({
16	  context: {
17	    printers: [
18	      ['BBL/Bambu Lab A1 mini', 'Bambu Lab A1 mini', '180 × 180 × 180 mm'],
19	      ['Prusa/Prusa MK3S', 'Prusa MK3S', '250 × 210 × 210 mm'],
20	      ['Vendor/Unmeasured', 'Vendor Unmeasured', ''],
21	    ],
22	    network: [],
23	  },
24	});
25	
26	const change = session({
27	  mode: 'change',
28	  printerName: 'Lab Printer',
29	  context: {
30	    printer: {
31	      name: 'Lab Printer',
